    # For "atlas help ...", dispatch to help.
    # For "atlas __complete ...", dispatch to complete.
    first = argv[0]
    if first.startswith("-"):
        try:
            flags, pos, _ = parse_flags(argv, TOP_SPECS)
        except FlagError as e:
            return handle_flag_error(str(e))
        if flags.get("help"):
