            cmd = pos[0]
            rest = pos[1:]
            # Note: original flags before -- are lost? But top only has help, so fine.
            if cmd == "schema":
                return cmd_schema(rest)
            elif cmd == "migrate":
                return cmd_migrate(rest)
            elif cmd == "version":
                return cmd_version(rest)
            elif cmd == "license":
                return cmd_license(rest)
            elif cmd == "completion":
                return cmd_completion(rest)
            elif cmd == "help":
                return cmd_help(rest)
            else:
                return handle_unknown_command(cmd)
        else:
            sys.stdout.write(HELP_TOP)
            return 0
    else:
