        if first == "help":
            return cmd_help(argv[1:])
        elif first == "version":
            return cmd_version(argv[1:])
        elif first == "license":
            return cmd_license(argv[1:])
        elif first == "completion":
            return cmd_completion(argv[1:])
        elif first == "schema":
            return cmd_schema(argv[1:])
        elif first == "migrate":
            return cmd_migrate(argv[1:])
        elif first == "__complete":
            return cmd_complete(argv[1:])
        elif first == "__completeNoDesc":
            # Cobra also has __completeNoDesc? Probably same as __complete with no descriptions. Let's handle similarly but without descriptions?
            # Original: does it support __completeNoDesc? Test later. For now, same as __complete but strip descriptions?
