def filter_realm(realm, schemas_filter, exclude_filter, include_filter):
    # Apply schemas/exclude/include filters to HCL realm (for file HCL cases, already have realm)
    # schemas_filter: list, exclude/include: lists
    # Returns new filtered realm (with source preserved)
    if (not schemas_filter or len(schemas_filter)==0) and (not exclude_filter or len(exclude_filter)==0) and (not include_filter or len(include_filter)==0):
        return realm
    new_realm = Realm()
    new_realm.source = getattr(realm, 'source', 'hcl')
    # Schemas: if schemas_filter specified, only keep those schemas
    keep_schemas = set(schemas_filter) if schemas_filter and len(schemas_filter)>0 else None
    for sname in realm.schema_order:
        if keep_schemas is not None and sname not in keep_schemas:
            continue
        new_realm.add_schema(sname)
    for (sname, tname) in realm.table_order:
        if keep_schemas is not None and sname not in keep_schemas:
            continue
        # Include filter (whitelist): if specified, must match to keep
        if include_filter and len(include_filter)>0:
            matched=False
            import fnmatch as _fn
            for pat in include_filter:
                if _fn.fnmatch(tname, pat) or _fn.fnmatch(f"{sname}.{tname}", pat):
                    matched=True
                    break
            if not matched:
                continue
        # Exclude filter (blacklist): if matches, skip
        if exclude_filter and len(exclude_filter)>0:
            excluded=False
            import fnmatch as _fn
            for pat in exclude_filter:
                if _fn.fnmatch(tname, pat) or _fn.fnmatch(f"{sname}.{tname}", pat):
                    excluded=True
                    break
            if excluded:
                continue
        new_realm.add_table(realm.tables[(sname, tname)])
    return new_realm

