            toks=[]
            ii=0; nn=len(inner)
            while ii<nn:
                if inner[ii] in ' \t':
                    ii+=1
                    continue
                elif inner[ii]=='"':
                    jj=ii+1; esc=False
                    while jj<nn:
                        if esc:
                            esc=False; jj+=1
                        elif inner[jj]=='\\':
                            esc=True; jj+=1
                        elif inner[jj]=='"':
                            jj+=1; break
                        else:
                            jj+=1
                    toks.append(inner[ii:jj]); ii=jj
                else:
                    jj=ii
                    while jj<nn and inner[jj] not in ' \t':
                        jj+=1
                    toks.append(inner[ii:jj]); ii=jj
            if len(toks)==0:
                out_parts.append("")
            else:
                func=toks[0]
                if func not in ("sql",):
                    return None, f'parse log format: template: format:1: function "{func}" not defined'
                if len(toks)<2 or toks[1]!=".":
                    return None, f'parse log format: template: format:1: unexpected "{toks[1] if len(toks)>1 else ""}" in operand'
                out_parts.append(plan_sql)
        last_end=end
    out_parts.append(format_str[last_end:])
    return "".join(out_parts), None

